ejemplo.codigo:
class Pila:
    def __init__(self):
        self._datos = []

    def push(self, x):
        self._datos.append(x)

    def pop(self):
        if not self._datos:
            raise IndexError("pila vacia")
        return self._datos.pop()

    def __len__(self):
        return len(self._datos)

p = Pila()
p.push(1)
p.push(2)
p.pop(), len(p)  # (2, 1)

